<template><view class="page"><view class="tabs"><text v-for="t in types" :key="t.value" :class="{active:type===t.value}" @tap="change(t.value)">{{t.label}}</text></view><view v-for="item in list" :key="item.id" class="card"><view class="head"><b>{{item.dataTypeText||item.dataType}}</b><text :class="item.riskLevel==='HIGH'?'danger':''">{{item.riskLevelText||''}}</text></view><view class="value">{{display(item)}}</view><view class="time">{{item.measuredAt}} {{item.periodCode||''}}</view></view><view v-if="!list.length" class="empty">暂无记录</view></view></template><script>import{getHealthDataList}from'@/api/health.js';export default{data(){return{type:'',list:[],types:[{label:'全部',value:''},{label:'血糖',value:'GLUCOSE'},{label:'饮食',value:'DIET'},{label:'运动',value:'EXERCISE'},{label:'用药',value:'MEDICINE'}]}},onShow(){this.load()},methods:{rows(r){const d=r&&r.data?r.data:r;return(d&&d.list)||d||[]},change(v){this.type=v;this.load()},load(){getHealthDataList({dataType:this.type,page:1,limit:100}).then(r=>this.list=this.rows(r)).catch(()=>this.list=[])},display(i){if(i.numericValue!=null)return i.numericValue+' '+(i.unit||'');try{const d=JSON.parse(i.detail||'{}');return d.content||d.category||d.remark||'已记录'}catch(e){return'已记录'}}}}</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.tabs{display:flex;overflow:auto;background:#fff;padding:18rpx;border-radius:18rpx;margin-bottom:20rpx}.tabs text{white-space:nowrap;padding:12rpx 24rpx;color:#777}.tabs .active{background:#19bf9b;color:#fff;border-radius:999rpx}.card{background:#fff;border-radius:18rpx;padding:24rpx;margin-bottom:16rpx}.head{display:flex;justify-content:space-between}.value{font-size:36rpx;font-weight:600;margin:18rpx 0}.time{font-size:23rpx;color:#999}.danger{color:#e44}.empty{text-align:center;color:#aaa;padding:100rpx}</style>